"""Kaggle kernel: run the benchmark-validated staleness auditor over the full CLAUDE.md corpus.

Reads the 110 (claim, artifact) pairs from the attached `dna-staleness-corpus` dataset and emits one
verdict per pair. The SYSTEM PROMPT and the user-turn shape are byte-identical to the ones the 10-item
benchmark scored (5/5 TP, 1 FP) -- if they drifted, the measured performance would not transfer, and the
whole point of running the benchmark first was to earn the right to trust this run.

Output is a FLAGGING pass, not a verdict on the docs: every `stale` flag is adjudicated by hand against
its artifact before any documentation changes. At the benchmark's measured 1-in-5 false-positive rate on
capability-shaped claims, that adjudication is the product, not an optional step.
"""
import json
import os

os.environ.setdefault("PYTHONUTF8", "1")
import torch
from transformers import AutoModelForCausalLM, AutoTokenizer

MODEL = "Qwen/Qwen3-8B"
MAX_NEW_TOKENS = 2500

SYSTEM = """You audit documentation claims for STALENESS.

You are given a CLAIM made in a project's documentation, and an EXCERPT of the ARTIFACT that claim is
about. Decide whether the artifact still SUPPORTS the claim.

Answer exactly one of:
  stale     - the artifact CONTRADICTS the claim (e.g. the claim says work is "deferred"/"pending"/
              "blocked" but the artifact shows it was DONE, or the claim states a number/status the
              artifact disagrees with)
  supported - the artifact is consistent with the claim, OR the text merely MENTIONS a deferral that
              refers to something ELSE (a different sub-task), OR the text is itself a CORRECTION
              explaining that something was previously mis-stated
  unclear   - the excerpt genuinely does not settle it

CRITICAL: prose often mentions "deferred" or "pending" NEAR a file path without the claim being about that
file. Do not flag on keyword proximity. Flag only when the artifact's CONTENT contradicts the claim's
SUBSTANCE. A sentence that says "X was deferred, and here is the correction recording that it shipped" is
`supported` -- it is accurate text about a past error, not a stale claim.

ARTIFACT FACTS are evidence too, but they are the LAST rule, not the first. Apply them ONLY after every
exception above has been checked, and ONLY to a CAPABILITY claim.

A CAPABILITY claim asserts something is NOT BUILT ("X is deferred", "the browser is not implemented",
"this is still pending"). For those, and only those, ARTIFACT FACTS showing implemented code REFUTE the
claim -> `stale`, even if the excerpt's prose repeats "deferred" (a module often describes itself as "the
deferred X" because it is the thing that finally implemented X).

Implemented code does NOT make a claim stale in any of these cases -- each is `supported`:
  - FINDING claims. "X is infeasible", "the substrate does not clear the bar", "the cohort is too small".
    The script is the INSTRUMENT that produced the finding; its existence is what makes the finding
    trustworthy. Code existing SUPPORTS a finding claim. This is the single most common error.
  - CORRECTION text. "X was deferred, and here is the correction recording that it shipped." Already
    stated above; it OUTRANKS this rule, it is not overridden by it.
  - HISTORICAL / past-tense claims. "the gates this family needed and did not have", "until 2026-08-25
    this line said X". A past-tense statement about what was missing is not refuted by the thing now
    existing.

When you cannot tell whether a claim is CAPABILITY or FINDING, answer `supported`. A missed stale claim
costs one unnoticed line; a false flag costs a human the time to check it.

Reply with STRICT JSON only, no prose outside it:
{"verdict": "stale|supported|unclear", "evidence": "<one sentence quoting what decided it>"}"""

ITEMS = [{"item_id": "b024_2_test_models_cache", "claim": "A mid-flush crash leaves a partial gene set that LOOKS like a complete strain to Stage 1. f9ed79f flush patch bounds loss to ~1 strain on crash but doesn't eliminate. **Consumer-side defense:** every mean-pool consumer MUST call `cache.verify_complete(expected_genes_by_strain) \u2192 CompletenessReport` and bail unless `report.all_complete` is True. Standalone audit CLI at `scripts/probe_nt_cache.py`. `tests/test_models_cache.py` pins the 4 status buckets + the `all_complete=False` rule on partial.", "artifact": "tests/test_models_cache.py", "facts": "exists: yes (23305 chars); implemented code: 48 function(s), 3 class(es)", "artifact_text": "\"\"\"Tests for Step 8 \u2014 HDF5 embedding cache.\"\"\"\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport numpy as np\nimport pytest\n\n# Skip the entire module if h5py is not installed (lighter test setups). The\n# real test run via `uv sync && pytest` installs h5py per pyproject.toml.\nh5py = pytest.importorskip(\"h5py\")\n\nfrom dna_decode.models.cache import (  # noqa: E402\n    CacheMetadata,\n    CompletenessReport,\n    EmbeddingCache,\n    EmbeddingCacheError,\n    EmbeddingCacheVersionMismatch,\n)\nfrom dna_decode.models.foundation import MockFoundationModel, ModelMetadata  # noqa: E402\n\n\n# ---- construction + metadata ----\n\n\ndef test_cache_creates_new_file_with_metadata(tmp_path: Path):\n    cache = EmbeddingCache(\n        tmp_path / \"cache.h5\",\n        model_name=\"mock\",\n        model_version=\"v1\",\n        embedding_dim=8,\n    )\n    md = cache.metadata()\n    assert md.model_name == \"mock\"\n    assert md.model_version == \"v1\"\n    assert md.embedding_dim == 8\n    assert md.created_at  # non-empty ISO timestamp\n\n\ndef test_cache_reopens_matching_existing_file(tmp_path: Path):\n    cache_path = tmp_path / \"cache.h5\"\n    EmbeddingCache(cache_path, \"mock\", \"v1\", 8)\n    # Re-open with matching params \u2192 no error\n    reopened = EmbeddingCache(cache_path, \"mock\", \"v1\", 8)\n    assert reopened.metadata().model_version == \"v1\"\n\n\ndef test_cache_version_mismatch_raises(tmp_path: Path):\n    cache_path = tmp_path / \"cache.h5\"\n    EmbeddingCache(cache_path, \"mock\", \"v1\", 8)\n    with pytest.raises(EmbeddingCacheVersionMismatch):\n        EmbeddingCache(cache_path, \"mock\", \"v2\", 8)\n\n\ndef test_cache_dim_mismatch_raises(tmp_path: Path):\n    cache_path = tmp_path / \"cache.h5\"\n    EmbeddingCache(cache_path, \"mock\", \"v1\", 8)\n    with pytest.raises(EmbeddingCacheVersionMismatch):\n        EmbeddingCache(cache_path, \"mock\", \"v1\", 16)\n\n\n# ---- pooling_strategy (Phase 2.5 hardening) ----\n\n\ndef test_cache_records_default_pooling_strategy(tmp_path: Path):\n    \"\"\"New caches default to 'single_seq_mean' for backward compat.\"\"\"\n    cache = EmbeddingCache(tmp_path / \"cache.h5\", \"mock\", \"v1\", 8)\n    assert cache.metadata().pooling_strategy == \"single_seq_mean\"\n\n\ndef test_cache_records_custom_pooling_strategy(tmp_path: Path):\n    cache = EmbeddingCache(\n        tmp_path / \"cache.h5\",\n        \"mock\",\n        \"v1\",\n        8,\n        pooling_strategy=\"mask_aware_mean\",\n    )\n    assert cache.metadata().pooling_strategy == \"mask_aware_mean\"\n\n\ndef test_cache_pooling_mismatch_raises(tmp_path: Path):\n    \"\"\"Reopening with different pooling_strategy \u2192 mismatch (prevents hybrid cache).\"\"\"\n    cache_path = tmp_path / \"cache.h5\"\n    EmbeddingCache(cache_path, \"mock\", \"v1\", 8, pooling_strategy=\"single_seq_mean\")\n    with pytest.raises(EmbeddingCacheVersionMismatch, match=\"pooling\"):\n        EmbeddingCache(cache_path, \"mock\", \"v1\", 8, pooling_strategy=\"mask_aware_mean\")\n\n\ndef test_cache_legacy_file_without_pooling_attr_accepts_default(tmp_path: Path):\n    \"\"\"Caches written pre-2026-05-13 lack the pooling attr; default-match should pass.\"\"\"\n    import h5py\n    cache_path = tmp_path / \"legacy.h5\"\n    # Hand-craft an old-shape cache: attrs match defaults except no pooling_strategy\n    with h5py.File(cache_path, \"w\") as f:\n        f.attrs[\"model_name\"] = \"mock\"\n        f.attrs[\"model_version\"] = \"v1\"\n        f.attrs[\"embedding_dim\"] = 8\n        f.attrs[\"created_at\"] = \"2026-01-01T00:00:00\"\n        f.create_group(\"strains\")\n        # NOTE: no pooling_strategy attribute\n\n    # Default constructor (pooling_strategy=\"single_seq_mean\") should match a legacy\n    # file without the attr \u2014 the reader defaults to \"single_seq_mean\".\n    reopened = EmbeddingCache(cache_path, \"mock\", \"v1\", 8)\n    assert reopened.metadata().pooling_strategy == \"single_seq_mean\"\n\n\n# ---- put / get round-trip ----\n\n\ndef test_put_get_round_trip(tmp_path: Path):\n    cache = EmbeddingCache(tmp_path / \"cache.h5\", \"mock\", \"v1\", 4)\n    emb = np.array([1.0, 2.0, 3.0, 4.0], dtype=np.float32)\n    cache.put(\"s001\", \"gene_X\", emb)\n    out = cache.get(\"s001\", \"gene_X\")\n    np.testing.assert_array_almost_equal(out, emb)\n\n\ndef test_put_wrong_shape_raises(tmp_path: Path):\n    cache = EmbeddingCache(tmp_path / \"cache.h5\", \"mock\", \"v1\", 8)\n    with pytest.raises(EmbeddingCacheError, match=\"shape\"):\n        cache.put(\"s001\", \"gene_X\", np.zeros(4))\n\n\ndef test_put_overwrites_existing(tmp_path: Path):\n    cache = EmbeddingCache(tmp_path / \"cache.h5\", \"mock\", \"v1\", 4)\n    cache.put(\"s001\", \"g\", np.array([1, 2, 3, 4], dtype=np.float32))\n    cache.put(\"s001\", \"g\", np.array([9, 9, 9, 9], dtype=np.float32))\n    out = cache.get(\"s001\", \"g\")\n    np.testing.assert_array_almost_equal(out, [9, 9, 9, 9])\n\n\ndef test_get_missing_returns_none(tmp_path: Path):\n    cache = EmbeddingCache(tmp_path / \"cache.h5\", \"mock\", \"v1\", 4)\n    assert cache.get(\"nonexistent\", \"missing\") is None\n\n\ndef test_has_returns_bool(tmp_path: Path):\n    cache = EmbeddingCache(tmp_path / \"cache.h5\", \"mock\", \"v1\", 4)\n    cache.put(\"s001\", \"g\", np.zeros(4, dtype=np.float32))\n    assert cache.has(\"s001\", \"g\")\n    assert not cache.has(\"s001\", \"absent\")\n    assert not cache.has(\"absent_strain\", \"g\")\n\n\ndef test_gene_id_with_slash_is_sanitized(tmp_path: Path):\n    \"\"\"HDF5 forbids '/' in group names; cache should sanitize to '__'.\"\"\"\n    cache = EmbeddingCache(tmp_path / \"cache.h5\", \"mock\", \"v1\", 4)\n    cache.put(\"s001\", \"gyrA/region\", np.zeros(4, dtype=np.float32))\n    assert cache.has(\"s001\", \"gyrA/region\")\n\n\n# ---- list operations ----\n\n\ndef test_list_strains_empty(tmp_path: Path):\n    cache = EmbeddingCache(tmp_path / \"cache.h5\", \"mock\", \"v1\", 4)\n    assert cache.list_strains() == []\n\n\ndef test_list_strains_returns_sorted(tmp_path: Path):\n    cache = EmbeddingCache(tmp_path / \"cache.h5\", \"mock\", \"v1\", 4)\n    cache.put(\"zeta\", \"g\", np.zeros(4, dtype=np.float32))\n    cache.put(\"alpha\", \"g\", np.zeros(4, dtype=np.float32))\n    cache.put(\"beta\", \"g\", np.zeros(4, dtype=np.float32))\n    assert cache.list_strains() == [\"alpha\", \"beta\", \"zeta\"]\n\n"}, {"item_id": "b033_1_bvbrc_strict_mic_4drug_censu", "claim": " at `data/processed/stage2_n150_cipro_cohort.parquet`; Databricks burst populating NT cache 2026-05-18). Cef may be v0.1 substrate if cef-S labels are backfilled from PATRIC/NARMS/EuSCAPE (deferred). Tet + gent dropped from Phase 2 candidate list. 4th-mechanism-class falsifier (gent) substrate also infeasible \u2014 needs a new candidate. See `wiki/bvbrc_strict_mic_4drug_census_2026-05-18.{md,json}` + `scripts/bvbrc_strict_mic_4drug_census.py`.", "artifact": "scripts/bvbrc_strict_mic_4drug_census.py", "facts": "exists: yes (28262 chars); implemented code: 11 function(s), 0 class(es)", "artifact_text": "\"\"\"BV-BRC strict-MIC 4-drug feasibility census.\n\nPhase 2 entry per `project_state/dna-decode-2026-05-11.md` Candidate-next-actions\nrow 1. Counts per-drug feasibility of building N=150 strict-MIC cohorts from\nBV-BRC AST data, gating each candidate strain through:\n\n  Stage 1: E. coli broth-microdilution AST rows for the drug\n  Stage 2: distinct genome IDs\n  Stage 3: with parseable MIC value\n  Stage 4: HIGH_R or HIGH_S strict-MIC classification (per drug breakpoints)\n  Stage 5: with assembly_accession (NCBI-downloadable)\n  Stage 6: passing assembly QC (contig_count <= 500, n50 >= 50_000)\n\nPer-drug breakpoints (CLSI 2024 + EUCAST 14.0 for E. coli):\n\n  - Ciprofloxacin: CLSI R>=2, S<=0.5  / EUCAST R>=1, S<=0.25\n  - Ceftriaxone:   CLSI R>=4, S<=1    / EUCAST R>=2, S<=1\n  - Tetracycline:  CLSI R>=16, S<=4   / EUCAST: no breakpoints for E. coli (ECOFF only)\n  - Gentamicin:    CLSI R>=16, S<=4   / EUCAST R>=4, S<=2  (aminoglycoside; 4th-mechanism-class)\n\nHIGH_R = median MIC >= 4 * CLSI-R breakpoint (4x safety margin)\nHIGH_S = median MIC <= CLSI-S / 4\n\nStrict-MIC pass = HIGH_R or HIGH_S only (BORDERLINE / AMBIGUOUS / CONFLICT / NO_MIC dropped).\n\nOutput: wiki/bvbrc_strict_mic_4drug_census_<date>.md + .json sidecar.\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport sys\nfrom collections import defaultdict\nfrom datetime import date as _date\nfrom math import isnan\nfrom pathlib import Path\nfrom typing import Optional\n\nimport pandas as pd\n\nfrom dna_decode.data.ast_data import load_bvbrc_ast\nfrom dna_decode.data.bvbrc_genome import load_bvbrc_genome_metadata\nfrom dna_decode.data.mic_tiers import (\n    DRUG_BREAKPOINTS,\n    breakpoints_for,\n    classify_tier as classify_strict_mic,\n)\n\n# Assembly QC thresholds (Stage 2 cohort builder default)\nDEFAULT_QC_MAX_CONTIGS = 500\nDEFAULT_QC_MIN_N50 = 50_000\n\n\n# ---------------------------------------------------------------------------\n# Per-drug census\n# ---------------------------------------------------------------------------\n\n\ndef census_drug(\n    ast: pd.DataFrame,\n    metadata: dict,\n    drug: str,\n    qc_max_contigs: int = DEFAULT_QC_MAX_CONTIGS,\n    qc_min_n50: int = DEFAULT_QC_MIN_N50,\n) -> dict:\n    \"\"\"Run the 6-stage feasibility census for one drug.\n\n    Returns a dict with stage counts + per-strain HIGH_R/HIGH_S breakdown\n    + the list of feasible strain_ids at the final stage.\n    \"\"\"\n    breakpoints = DRUG_BREAKPOINTS.get(drug.lower())\n    if breakpoints is None:\n        raise ValueError(f\"No breakpoints configured for drug: {drug!r}\")\n\n    drug_ast = ast[ast[\"antibiotic\"].str.lower() == drug.lower()].copy()\n    stage1_total_ast_rows = len(drug_ast)\n\n    distinct_genomes = drug_ast[\"strain_id\"].dropna().unique()\n    stage2_distinct_genomes = len(distinct_genomes)\n\n    # Aggregate MIC + label per strain\n    per_strain: dict[str, dict] = defaultdict(lambda: {\"mics\": [], \"labels\": set()})\n    for _, row in drug_ast.iterrows():\n        sid = str(row[\"strain_id\"]).strip()\n        if not sid:\n            continue\n        mic = row.get(\"mic_value\")\n        if mic is not None and not (isinstance(mic, float) and isnan(mic)):\n            per_strain[sid][\"mics\"].append(float(mic))\n        label = str(row.get(\"susceptibility_label\", \"\")).strip().upper()\n        if label:\n            per_strain[sid][\"labels\"].add(label)\n\n    stage3_with_mic = sum(1 for s in per_strain.values() if s[\"mics\"])\n\n    # Classify each strain. `load_bvbrc_ast` keeps `susceptibility_label` as the\n    # uppercased string (\"R\" / \"RESISTANT\" / \"S\" / \"SUSCEPTIBLE\" / \"I\" /\n    # \"INTERMEDIATE\"); binarization happens downstream at `get_binary_labels` /\n    # `candidates_from_bvbrc_ast`, not here. We pass the raw label set directly.\n    classifications: dict[str, str] = {}\n    strict_r: list[str] = []      # HIGH_R only\n    strict_s: list[str] = []      # HIGH_S only\n    decisive_r: list[str] = []    # DECISIVE_R (between 2x and 4x CLSI-R)\n    decisive_s: list[str] = []    # DECISIVE_S (between CLSI_S/4 and CLSI_S/2)\n    bucket_counts: dict[str, int] = defaultdict(int)\n    for sid, agg in per_strain.items():\n        distinct_calls = set(agg[\"labels\"])\n        tier = classify_strict_mic(agg[\"mics\"], distinct_calls, breakpoints)\n        classifications[sid] = tier\n        bucket_counts[tier] += 1\n        if tier == \"HIGH_R\":\n            strict_r.append(sid)\n        elif tier == \"HIGH_S\":\n            strict_s.append(sid)\n        elif tier == \"DECISIVE_R\":\n            decisive_r.append(sid)\n        elif tier == \"DECISIVE_S\":\n            decisive_s.append(sid)\n\n    stage4_strict_mic = len(strict_r) + len(strict_s)\n    stage4_relaxed_mic = stage4_strict_mic + len(decisive_r) + len(decisive_s)\n\n    # Stage 5: with assembly_accession. Note: `load_bvbrc_genome_metadata`\n    # already drops rows lacking assembly_accession at parse time, so this\n    # check primarily filters strains whose strain_id has no metadata entry\n    # at all (returns {} \u2192 empty accession).\n    def _has_accession(sid: str) -> bool:\n        meta = metadata.get(sid, {})\n        acc = str(meta.get(\"assembly_accession\", \"\")).strip()\n        return bool(acc) and acc.lower() not in (\"nan\", \"none\")\n\n    # Stage 6: assembly QC\n    def _passes_qc(sid: str) -> bool:\n        meta = metadata.get(sid, {})\n        try:\n            contigs = int(meta.get(\"contig_count\", 0) or 0)\n            n50 = int(meta.get(\"n50\", 0) or 0)\n        except (TypeError, ValueError):\n            return False\n        return contigs > 0 and contigs <= qc_max_contigs and n50 >= qc_min_n50\n\n    def _filter_pipeline(strains: list[str]) -> tuple[list[str], list[str]]:\n        with_acc = [s for s in strains if _has_accession(s)]\n        with_qc = [s for s in with_acc if _passes_qc(s)]\n        return with_acc, with_qc\n\n    strict_r_acc, strict_r_qc = _filter_pipeline(strict_r)\n    strict_s_acc, strict_s_qc = _filter_pipeline(strict_s)\n    decisive_r_acc, decisive_r_qc = _filter_pipeline(decisive_r)\n    decisive_s_acc, decisive_s_qc = _filter_pipeline("}, {"item_id": "b062_2_negative_results_map_2026-06", "claim": "self_retiring` pins that). Impact of the drift itself stays LOW (the NT-embedding track is a closed negative); a `transformers` pin would touch every cell and is deliberately NOT applied. **Why this mattered beyond cosmetics: a permanently-red suite trains readers to discount red, which is how a genuine new failure gets missed** \u2014 that failure was hand-discounted a dozen times in one session**) + `wiki/negative_results_map_2026-06-13.md` (**10** reusable rejection GATES \u2014 G1-G8 gate whether a usable LABEL exists; **G9/G10 (added 2026-08-26) gate whether the decoder's own RULE is scoreable against a genotype at all** \u2014 circular-label / study==class / sampling-defined / surveillance-domination / assembly-attrition / MIC-censoring / provenance-not-separable / dedup-collapses-balance \u2014 screen any new candidate dataset against these B", "artifact": "wiki/negative_results_map_2026-06-13.md", "facts": "exists: yes (8982 chars)", "artifact_text": "# Operational negative-results map \u2014 why each G2P expansion was rejected (2026-06-13)\n\n**Purpose:** This is NOT a prose graveyard of failed attempts. It is an *operational* map: each rejected\nexpansion is encoded as a reusable GATE so future work (future-you, or anyone forking this tool) can\nscreen a candidate dataset/trait against the failure modes BEFORE spending labor. The recurring lesson \u2014\nverified across every closed track this project ran \u2014 is that **honest public bacterial genotype\u2192phenotype\ndecoding is bounded by LABELS, not models.** A candidate that trips any gate below cannot support an honest\nlearned decoder on available public data.\n\nThis map is the scientific contribution that accompanies the shipped deterministic AMR decoder: it states\nthe boundary of what public G2P can honestly support, so the tool is never overextended into a dishonest\nregime.\n\n## The 10 rejection gates (screen every candidate against these)\n\n| # | Gate | Trips when | How to check (cheap) |\n|---|---|---|---|\n| G1 | **Circular label** | the phenotype label is itself produced by a genomic tool the decoder would compete against (AMRFinder / BlastFrost / any genome\u2192label model) | inspect label provenance field / dataset methods \u2014 is the label wet-lab/clinical or gene-call-derived? |\n| G2 | **Study == class** | the label is confounded with the source study / submitter (one BioProject supplies most of one class) | contingency table of class \u00d7 BioProject/submitter; a dominant cell = trip |\n| G3 | **Sampling-defined label** | the label IS the sampling context, not a measurement (e.g. blood-vs-feces = pathotype by definition) | ask: is the label an assay reading, or a description of where/why the isolate was collected? |\n| G4 | **Surveillance domination** | excluding the surveillance ecosystem (NARMS/CDC/FDA/GenomeTrakr/PulseNet/USDA) collapses the resistant/positive pool below a usable cohort | census the OTHER (non-ecosystem) class counts; <20/class = trip |\n| G5 | **Assembly attrition** | label-bearing records exist but lack downloadable assemblies (the historical ~96% drop) | count records WITH `assembly_accession` that NCBI Datasets can fetch, not raw record count |\n| G6 | **Phenotype censoring** | the quantitative label is interval-censored exactly where it matters (MIC `>X` / `<=X` at the breakpoint) | tally exact vs censored values among the in-class subset; majority-censored = trip |\n| G7 | **Provenance not separable** | metadata is too thin to build a leakage-clean provenance-disjoint split | are submitter / center / collection fields populated per-record? absent = trip |\n| G8 | **Dedup collapses balance** | after Mash-lineage clonality correction, one class drops below usable effective-N (clonally dominated) | greedy-representative Mash cluster per class; <~3 effective lineages = trip |\n| G9 | **Causal variant unrecorded** (added 2026-08-26) | the decoder's rule names allele SYMBOLS and dominance order but never the causal VARIANT, so no genotype file can be scored against it \u2014 unvalidatable as written, and no cohort fixes it | for each locus, does the catalog record a concrete variant (`c.` / `p.` / a named indel)? Count unrecorded loci; a majority = trip. Measured: **40 of 65 colour-cell loci (62%) record none**, and 7 of 19 cells record none for ANY locus (`wiki/colour_cell_substrate_screen_2026-08-26.md`) |\n| G10 | **Variant class off-panel** (added 2026-08-26) | the causal variants ARE recorded but are indels / structural / CNV, which a SNP array or imputed biallelic-SNV panel cannot represent \u2014 so the commonest free genotype cohorts cannot score the rule however good it is | classify each recorded causal variant as SNV vs indel/structural; count the off-panel share. Measured: **14 of 25 recorded colour-cell variants (56%) are indel/structural**, and this is what sank the dog cell empirically \u2014 black 0.994 but every other base colour unscorable (`wiki/dog_coat_darwins_ark_measured_2026-07-30.md`) |\n\n## The verified failure record (each row = a closed track + the gates it tripped)\n\n| Track | Verdict | Gates tripped | Evidence |\n|---|---|---|---|\n| Pathotype (EnteroBase / NCBI-PD labels) | label-blocked | G1 (BlastFrost/AMRFinder-derived), G3 (isolation-site), G2 (study==class on the 24-genome ExPEC/EPEC) | `research_outputs/horesh-f1-label-provenance-audit-2026-06-04.md` (H1 falsified; curated-independent fraction 20.5%) |\n| Foundation-model embeddings (0-for-4) | embedding learns lineage not mechanism | (not a label gate \u2014 a MODEL ceiling) | `wiki/embedding_niche_cross_domain_synthesis_2026-06-12.md` (cipro within-lineage=chance; Arabidopsis within-group r2 \u22120.13) |\n| MIC-continuous (graded resistance) | not-feasible | G1 (91% of BV-BRC MIC is XGBoost-from-genome), G6 (~70% breakpoint-censored), G8 (within-R exact N=6) | ledger action 91 (`project_state/dna-decode-2026-05-11.md`); probe 2026-06-13 |\n| AMR grid \u2014 Salmonella tet/gent | underpowered, infeasible | G4 (ecosystem-dominated: tet 4871R ecosystem \u2192 4R disjoint) | ledger action 79; `wiki/provdisjoint_census_results.json` |\n| AMR grid \u2014 Acinetobacter/Pseudomonas/Klebsiella-class broad expansion | intrinsic-gene degeneracy | (mechanism ceiling \u2014 intrinsic class-genes over-call, spec\u21920) | `~/.claude/...memory/feedback_intrinsic_genes_break_broad_amr_class_rules.md` |\n| Cross-organism catalog transfer (g8r2 \u2014 \"zero target labels\" bypass) | label-wall NOT bypassed + already-built | (not a new label gate \u2014 the naive unchanged transfer FAILS per-organism on threshold/content, so target labels are still needed to calibrate) | `wiki/wider_amr_transferability_synthesis_2026-06-08.md` (Campylobacter/Salmonella cipro FAIL: TUNING/CONTENT); `wiki/innovate_round2_frontier_closeout_2026-07-13.md` |\n| Self-supervised catalog (g5r2 \u2014 train an effect-predictor on the catalog itself) | no negative class / circular where one exists | (not a new label gate \u2014 3/4 cells are all-positive DRM sets; WHO-TB grades ARE distilled phenotype \u2192 self-prediction is circul"}, {"item_id": "b068_4_browser", "claim": "nome-map tests (`tests/test_genome_map_*.py`); FROZEN AMR surface (`amr_rules.py` + `calibrated_amr_rules.json`) byte-unchanged (READ-only overlay). TB/fungal out of the v1 spike (VCF-vs-GFF contract); pathway/KEGG + hmmer/Pfam/eggNOG tiers deferred. (Until 2026-08-25 this line ALSO listed the visual browser as deferred, CONTRADICTING the next bullet -- the graphical browser SHIPPED 2026-07-11 as `dna_decode/genome_map/browser.py` + `scripts/genome_map_browser.py`.) **Contig-length-collision ambiguity count SHIPPED 2026-06-28** (`phenotype_overlay.contig_collision_count` pure helper \u2192 threaded via `run_genome_map_for` \u2192 `build_genome_map(contig_reconciliation=\u2026)` \u2192 `metrics[\"contig_reconciliation\"]` \u2192 `render_genome_summary_md`): surfaces `n_reconciled` / `n_fasta_ambiguous_contigs` / `n_bakta_ambiguous_contigs` so the REA", "artifact": "dna_decode/genome_map/browser.py", "facts": "exists: yes (12547 chars); implemented code: 9 function(s), 0 class(es)", "artifact_text": "\"\"\"Standalone graphical browser for a genome-map JSON \u2014 the deferred v1 \"graphical browser\".\n\nPure + dependency-free: `build_genome_map_html(genome_map, ...)` turns the same map dict that\n`scripts/genome_map.py` produces (and `render_genome_summary_md` renders as text) into a single\nself-contained HTML file \u2014 one horizontal track per contig, every feature a block positioned by\n`start`/`end` and coloured by `primary_tier`, with the AMR/virulence determinant features surfaced and\nlabelled. No external JS/CSS libraries, no network, no new dependency; the map JSON is the only input.\n\nTHE HONESTY WALL CARRIES INTO THE VISUAL (this is the whole point of the map):\n  - Only `determinant-phenotype` (and, separately, `virulence-determinant`) features show a phenotype /\n    pathotype claim. Every other tier is a molecular-function / homology / unknown annotation with NO\n    phenotype \u2014 the browser never colours a phenotype onto them.\n  - The `unknown_under_bakta_db_light` rate, `overlay_status`, and `all_joins_symbol_fallback` render as a\n    prominent caveat banner, not buried.\n  - The whole-contig `region` backbone feature defines each track's length and is NOT drawn as a block\n    (it would otherwise cover the entire track \u2014 the same feature the coord-join excludes).\n\"\"\"\nfrom __future__ import annotations\n\nimport html\nfrom datetime import date as _date\n\n# tier -> (colour, track-height px, z-order, legend label). Determinant/virulence are tallest + on top.\n_TIER_STYLE: dict[str, tuple[str, int, int, str]] = {\n    \"determinant-phenotype\": (\"#c0392b\", 20, 6, \"determinant-phenotype \u2014 AMR phenotype claim (behind the wall)\"),\n    \"virulence-determinant\": (\"#8e44ad\", 18, 5, \"virulence-determinant \u2014 curated VF present (presence only)\"),\n    \"curated-molecular-function\": (\"#2980b9\", 9, 3, \"curated-molecular-function\"),\n    \"homology-only-hypothesis\": (\"#e67e22\", 7, 2, \"homology-only-hypothesis\"),\n    \"unknown\": (\"#95a5a6\", 6, 1, \"unknown (db-light coverage caveat)\"),\n    \"secondary-evidence\": (\"#bdc3c7\", 6, 1, \"secondary-evidence\"),\n}\n_DEFAULT_STYLE = (\"#7f8c8d\", 6, 1, \"other\")\n_BACKBONE_TYPES = {\"region\"}\n\n\ndef _e(x) -> str:\n    return html.escape(str(x if x is not None else \"\"), quote=True)\n\n\ndef contig_lengths(features: list[dict]) -> dict[str, int]:\n    \"\"\"{seqid: length}. Prefer the whole-contig `region` backbone; else fall back to the max `end`.\"\"\"\n    region: dict[str, int] = {}\n    max_end: dict[str, int] = {}\n    for f in features:\n        sid = f.get(\"seqid\")\n        if sid is None:\n            continue\n        end = int(f.get(\"end\") or 0)\n        max_end[sid] = max(max_end.get(sid, 0), end)\n        if f.get(\"raw_feature_type\") in _BACKBONE_TYPES:\n            region[sid] = max(region.get(sid, 0), end)\n    # prefer the region backbone length; fall back to the max feature end for contigs without one\n    return {sid: region.get(sid, max_end[sid]) for sid in max_end}\n\n\ndef _feature_label(f: dict) -> str:\n    if f.get(\"raw_gene_symbol\"):\n        return f[\"raw_gene_symbol\"]\n    # for a determinant-phenotype feature with no gene symbol, the curated determinant symbol\n    # (e.g. `parC_E84V`) is far more informative than the strain-unique locus tag.\n    dets = [p.get(\"determinant_symbol\") for p in (f.get(\"phenotype\") or []) if p.get(\"determinant_symbol\")]\n    if dets:\n        return \", \".join(dict.fromkeys(dets))   # dedup, preserve order\n    return f.get(\"raw_locus_tag\") or (f.get(\"raw_product\") or \"\")[:60] or f.get(\"raw_feature_type\") or \"feature\"\n\n\ndef _feature_tooltip(f: dict) -> str:\n    parts = [\n        f\"{_feature_label(f)}\",\n        f\"tier: {f.get('primary_tier')}\",\n        f\"{f.get('seqid')}:{f.get('start')}-{f.get('end')} ({f.get('strand')})\",\n        f\"type: {f.get('raw_feature_type')}\",\n    ]\n    if f.get(\"raw_product\"):\n        parts.append(f\"product: {f['raw_product']}\")\n    pheno = f.get(\"phenotype\") or []\n    for p in pheno:\n        det = p.get(\"determinant_symbol\") or p.get(\"gene\") or \"\"\n        drug = p.get(\"drug\") or p.get(\"phenotype\") or \"\"\n        pred = p.get(\"genome_prediction\") or p.get(\"phenotype\") or \"\"\n        if det or drug:\n            parts.append(f\"  {det} \u2192 {drug} = {pred}\")\n    return \" | \".join(str(x) for x in parts)\n\n\ndef _blocks_for_contig(features: list[dict], seqid: str, length: int) -> str:\n    \"\"\"Absolutely-positioned feature blocks for one contig, scaled to [0, length].\"\"\"\n    if length <= 0:\n        return \"\"\n    rows: list[dict] = [\n        f for f in features\n        if f.get(\"seqid\") == seqid and f.get(\"raw_feature_type\") not in _BACKBONE_TYPES\n        and f.get(\"start\") is not None and f.get(\"end\") is not None\n    ]\n    rows.sort(key=lambda f: _TIER_STYLE.get(f.get(\"primary_tier\"), _DEFAULT_STYLE)[2])  # tallest last (on top)\n    out: list[str] = []\n    for f in rows:\n        tier = f.get(\"primary_tier\") or \"unknown\"\n        color, h, _z, _lbl = _TIER_STYLE.get(tier, _DEFAULT_STYLE)\n        s, e = int(f[\"start\"]), int(f[\"end\"])\n        left = max(0.0, min(100.0, 100.0 * s / length))\n        width = max(0.06, min(100.0 - left, 100.0 * (e - s) / length))  # min width so a point is visible\n        tier_class = \"t-\" + tier.replace(\" \", \"_\")\n        labelled = tier in (\"determinant-phenotype\", \"virulence-determinant\")\n        label_html = (f'<span class=\"flabel\">{_e(_feature_label(f))}</span>' if labelled else \"\")\n        out.append(\n            f'<div class=\"feat {tier_class}\" style=\"left:{left:.4f}%;width:{width:.4f}%;'\n            f'height:{h}px;background:{color};\" title=\"{_e(_feature_tooltip(f))}\">{label_html}</div>'\n        )\n    return \"\\n\".join(out)\n\n\ndef _metrics_header(gm: dict) -> str:\n    m = gm.get(\"metrics\", {})\n    per_tier = m.get(\"per_tier_counts\", {})\n    chips = \"\".join(\n        f'<span class=\"chip\" style=\"background:{_TIER_STYLE.get(k, _DEFAULT_STYLE)[0]}\">{_e(k)}: {_e(v)}</span>'\n        for k, v in per_tier.items()\n    )\n    calls = m.get(\"genome_level_calls\", {}) or {}\n    call_str = \", \".join(f\"{_e(d)}={_e(v.get('prediction'))}\" for d, v"}, {"item_id": "b078_4_negative_results_map_2026-06", "claim": "data; (2) of the 25 loci that DO record one, **14 (56%) are indel/structural** \u2014 off-panel for any SNP array, which is empirically what sank the one measured cell (dog: black 160/161 = **0.994**, every other base colour unscorable, `wiki/dog_coat_darwins_ark_measured_2026-07-30.md`). Only **donkey (3/3)** and **roe deer (1/1)** are fully SNV-tractable. **Screen a candidate against gates G9/G10 in `wiki/negative_results_map_2026-06-13.md` BEFORE building it** \u2014 G1\u2013G8 gate whether a usable LABEL exists; **G9/G10 gate whether the decoder's own rule is SCOREABLE against a genotype at all**, and they are the decoder-side gates this family needed and did not have. Run `uv run python scripts/colour_cell_substrate_screen.py` (`--self-check` first; no network, no GPU). **HONESTY: the freeze is an attention/scope guard, NOT enforcement** \u2014", "artifact": "wiki/negative_results_map_2026-06-13.md", "facts": "exists: yes (8982 chars)", "artifact_text": "# Operational negative-results map \u2014 why each G2P expansion was rejected (2026-06-13)\n\n**Purpose:** This is NOT a prose graveyard of failed attempts. It is an *operational* map: each rejected\nexpansion is encoded as a reusable GATE so future work (future-you, or anyone forking this tool) can\nscreen a candidate dataset/trait against the failure modes BEFORE spending labor. The recurring lesson \u2014\nverified across every closed track this project ran \u2014 is that **honest public bacterial genotype\u2192phenotype\ndecoding is bounded by LABELS, not models.** A candidate that trips any gate below cannot support an honest\nlearned decoder on available public data.\n\nThis map is the scientific contribution that accompanies the shipped deterministic AMR decoder: it states\nthe boundary of what public G2P can honestly support, so the tool is never overextended into a dishonest\nregime.\n\n## The 10 rejection gates (screen every candidate against these)\n\n| # | Gate | Trips when | How to check (cheap) |\n|---|---|---|---|\n| G1 | **Circular label** | the phenotype label is itself produced by a genomic tool the decoder would compete against (AMRFinder / BlastFrost / any genome\u2192label model) | inspect label provenance field / dataset methods \u2014 is the label wet-lab/clinical or gene-call-derived? |\n| G2 | **Study == class** | the label is confounded with the source study / submitter (one BioProject supplies most of one class) | contingency table of class \u00d7 BioProject/submitter; a dominant cell = trip |\n| G3 | **Sampling-defined label** | the label IS the sampling context, not a measurement (e.g. blood-vs-feces = pathotype by definition) | ask: is the label an assay reading, or a description of where/why the isolate was collected? |\n| G4 | **Surveillance domination** | excluding the surveillance ecosystem (NARMS/CDC/FDA/GenomeTrakr/PulseNet/USDA) collapses the resistant/positive pool below a usable cohort | census the OTHER (non-ecosystem) class counts; <20/class = trip |\n| G5 | **Assembly attrition** | label-bearing records exist but lack downloadable assemblies (the historical ~96% drop) | count records WITH `assembly_accession` that NCBI Datasets can fetch, not raw record count |\n| G6 | **Phenotype censoring** | the quantitative label is interval-censored exactly where it matters (MIC `>X` / `<=X` at the breakpoint) | tally exact vs censored values among the in-class subset; majority-censored = trip |\n| G7 | **Provenance not separable** | metadata is too thin to build a leakage-clean provenance-disjoint split | are submitter / center / collection fields populated per-record? absent = trip |\n| G8 | **Dedup collapses balance** | after Mash-lineage clonality correction, one class drops below usable effective-N (clonally dominated) | greedy-representative Mash cluster per class; <~3 effective lineages = trip |\n| G9 | **Causal variant unrecorded** (added 2026-08-26) | the decoder's rule names allele SYMBOLS and dominance order but never the causal VARIANT, so no genotype file can be scored against it \u2014 unvalidatable as written, and no cohort fixes it | for each locus, does the catalog record a concrete variant (`c.` / `p.` / a named indel)? Count unrecorded loci; a majority = trip. Measured: **40 of 65 colour-cell loci (62%) record none**, and 7 of 19 cells record none for ANY locus (`wiki/colour_cell_substrate_screen_2026-08-26.md`) |\n| G10 | **Variant class off-panel** (added 2026-08-26) | the causal variants ARE recorded but are indels / structural / CNV, which a SNP array or imputed biallelic-SNV panel cannot represent \u2014 so the commonest free genotype cohorts cannot score the rule however good it is | classify each recorded causal variant as SNV vs indel/structural; count the off-panel share. Measured: **14 of 25 recorded colour-cell variants (56%) are indel/structural**, and this is what sank the dog cell empirically \u2014 black 0.994 but every other base colour unscorable (`wiki/dog_coat_darwins_ark_measured_2026-07-30.md`) |\n\n## The verified failure record (each row = a closed track + the gates it tripped)\n\n| Track | Verdict | Gates tripped | Evidence |\n|---|---|---|---|\n| Pathotype (EnteroBase / NCBI-PD labels) | label-blocked | G1 (BlastFrost/AMRFinder-derived), G3 (isolation-site), G2 (study==class on the 24-genome ExPEC/EPEC) | `research_outputs/horesh-f1-label-provenance-audit-2026-06-04.md` (H1 falsified; curated-independent fraction 20.5%) |\n| Foundation-model embeddings (0-for-4) | embedding learns lineage not mechanism | (not a label gate \u2014 a MODEL ceiling) | `wiki/embedding_niche_cross_domain_synthesis_2026-06-12.md` (cipro within-lineage=chance; Arabidopsis within-group r2 \u22120.13) |\n| MIC-continuous (graded resistance) | not-feasible | G1 (91% of BV-BRC MIC is XGBoost-from-genome), G6 (~70% breakpoint-censored), G8 (within-R exact N=6) | ledger action 91 (`project_state/dna-decode-2026-05-11.md`); probe 2026-06-13 |\n| AMR grid \u2014 Salmonella tet/gent | underpowered, infeasible | G4 (ecosystem-dominated: tet 4871R ecosystem \u2192 4R disjoint) | ledger action 79; `wiki/provdisjoint_census_results.json` |\n| AMR grid \u2014 Acinetobacter/Pseudomonas/Klebsiella-class broad expansion | intrinsic-gene degeneracy | (mechanism ceiling \u2014 intrinsic class-genes over-call, spec\u21920) | `~/.claude/...memory/feedback_intrinsic_genes_break_broad_amr_class_rules.md` |\n| Cross-organism catalog transfer (g8r2 \u2014 \"zero target labels\" bypass) | label-wall NOT bypassed + already-built | (not a new label gate \u2014 the naive unchanged transfer FAILS per-organism on threshold/content, so target labels are still needed to calibrate) | `wiki/wider_amr_transferability_synthesis_2026-06-08.md` (Campylobacter/Salmonella cipro FAIL: TUNING/CONTENT); `wiki/innovate_round2_frontier_closeout_2026-07-13.md` |\n| Self-supervised catalog (g5r2 \u2014 train an effect-predictor on the catalog itself) | no negative class / circular where one exists | (not a new label gate \u2014 3/4 cells are all-positive DRM sets; WHO-TB grades ARE distilled phenotype \u2192 self-prediction is circul"}]
items = ITEMS
print(f"loaded {len(items)} pairs (6000-char excerpts, v3 prompt)", flush=True)
print("device:", torch.cuda.get_device_name(0) if torch.cuda.is_available() else "CPU", flush=True)

tok = AutoTokenizer.from_pretrained(MODEL)
model = AutoModelForCausalLM.from_pretrained(MODEL, torch_dtype=torch.bfloat16, device_map="auto")
model.eval()

out = []
for n, it in enumerate(items, 1):
    user = (f"CLAIM (from project documentation):\n{it['claim']}\n\n"
            f"ARTIFACT the claim is about: {it['artifact']}\n"
            f"ARTIFACT FACTS: {it.get('facts','')}\n"
            f"ARTIFACT EXCERPT:\n{it['artifact_text']}\n\n"
            f"Does the artifact still support the claim?")
    msgs = [{"role": "system", "content": SYSTEM}, {"role": "user", "content": user}]
    text = tok.apply_chat_template(msgs, tokenize=False, add_generation_prompt=True)
    ids = tok([text], return_tensors="pt").to(model.device)
    with torch.no_grad():
        gen = model.generate(**ids, max_new_tokens=MAX_NEW_TOKENS, do_sample=False)
    raw = tok.decode(gen[0][ids.input_ids.shape[-1]:], skip_special_tokens=True)
    out.append({"item_id": it["item_id"], "artifact": it["artifact"], "raw": raw})
    if n % 10 == 0 or n == len(items):
        # checkpoint as we go: a 110-item run that dies at item 90 must not lose 90 items of work
        json.dump(out, open("/kaggle/working/results.json", "w", encoding="utf-8"), indent=2)
        print(f"[{n}/{len(items)}] checkpointed", flush=True)

json.dump(out, open("/kaggle/working/results.json", "w", encoding="utf-8"), indent=2)
